#pragma once

#include <cstdint>
#include <memory>
#include <optional>
#include <string_view>
#include <vector>

namespace duckemu::runtime::vfs
{

// One entry a synthetic mount answers for. Files carry their whole immutable
// content; every open descriptor shares it.
struct SyntheticNode
{
	bool directory = false;
	std::shared_ptr<const std::vector<uint8_t> > content;
};

// Read-only mounts that live outside the host roots. /proc is generated by the
// existing ProcFs; this interface is for fixed namespaces (/dev/__properties__
// is the first client, /dev nodes are the next). Lookup takes a normalized
// absolute guest path.
class SyntheticFileSystem
{
    public:
	virtual ~SyntheticFileSystem() = default;

	[[nodiscard]] virtual std::optional<SyntheticNode> lookup(
		std::string_view guest_path) const = 0;
};

} // namespace duckemu::runtime::vfs
